const L=[];const p=(n,v)=>L.push(n+"="+JSON.stringify(v));
p("basic",[/a+b/.test("aab"),/^x/.test("yx"),"a1b2".match(/\d/g)]);
p("groups",(()=>{const m=/(\w+)@(\w+)/.exec("me@host");return[m[0],m[1],m[2],m.index]})());
p("named",/(?<y>\d{4})-(?<m>\d{2})/.exec("2024-06").groups);
p("backrefs",[/(a)\1/.test("aa"),/(a)\1/.test("ab")]);
p("lookahead",[/a(?=b)/.test("ab"),/a(?!b)/.test("ac"),/(?<=a)b/.test("ab"),/(?<!a)b/.test("cb")]);
p("lazy",["aaa".match(/a+?/)[0],"<x><y>".match(/<.+?>/)[0]]);
p("alternation",["cat dog".replace(/cat|dog/g,"pet")]);
p("classes",["a-b_c 1".replace(/[\W]/g,"."), /[^a-z]/.test("abc"), /[\d-]/.test("-")]);
p("anchors",[/^ab$/.test("ab"),/\bword\b/.test("a word here")]);
p("flags i/m/s",[/AB/i.test("ab"), "a\nb".match(/^b/m)[0], /a.b/s.test("a\nb")]);
p("sticky",(()=>{const r=/\d+/y;r.lastIndex=2;const m=r.exec("ab12cd");return[m&&m[0],r.lastIndex]})());
p("global exec state",(()=>{const r=/\d/g;const a=[];let m;while((m=r.exec("a1b2c3")))a.push(m[0]);return a})());
p("unicode",[/\u{1F600}/u.test("😀"), /\p{L}/u.test("é"), /\p{Script=Greek}/u.test("α")]);
p("v flag",(()=>{try{return[new RegExp("[\\p{L}--[a-z]]","v").test("A")]}catch(e){return e.constructor.name}})());
p("dup named",(()=>{try{return new RegExp("(?<x>a)|(?<x>b)").exec("b").groups.x}catch(e){return e.constructor.name}})());
p("modifiers",(()=>{try{return[new RegExp("(?i:AB)c").test("abc")]}catch(e){return e.constructor.name}})());
p("replace fns",["a1b2".replace(/\d/g,(m)=>m*2), "x-y".replace(/(-)/,"[$1]")]);
p("split",["a1b22c".split(/\d+/), "abc".split(/(?:)/)]);
p("matchAll",[...("a1b2".matchAll(/\d/g))].map(m=>m[0]));
p("source/flags",[/ab/gi.source,/ab/gi.flags,new RegExp("x","u").unicode]);
p("escape edge",[/\$/.test("$"), "a.b".split(".").length, /[/]/.test("/")]);
p("empty match",["ab".replace(/(?:)/g,"-")]);
p("large input",(()=>{const s="x".repeat(10000)+"y";return[/x*y/.test(s), s.match(/y/).index]})());
p("catastrophic-ish",(()=>{const t=performance.now();const r=/^(a+)+$/.test("aaaaaaaaaaaaaaaaaaaaX");return[r,performance.now()-t<2000]})());
console.log(L.join("\n"));
